SET part.parent_part_id = NULL,
    part.linked_piece_id = (SELECT linked.id FROM pieces linked WHERE linked.id = 14907 AND linked.composer_id = 4),
    part.sequence_number = 1, part.movement_number = 'I',
    part.name_ko = '합창 "Wie schön leuchtet der Morgenstern"', part.name_en = 'I. Coro "Wie schön leuchtet der Morgenstern"',
    part.editorial_status = 'EDITOR_REVIEWED', part.editor_locked = 1
