-- BWV 806–811 영국 모음곡

UPDATE pieces piece
SET piece.title = '영국 모음곡', piece.title_en = 'English Suites, BWV 806–811',
    piece.type = 'album', piece.opus_number = 'BWV 806–811',
    piece.catalogue_system = NULL, piece.catalogue_number = NULL,
    piece.composition_year = COALESCE(1725, piece.composition_year),
    piece.editor_locked = 1
WHERE piece.id = 15471 AND piece.composer_id = 4
  AND piece.origin = 'seed' AND piece.editor_locked = 0;
UPDATE pieces piece
SET piece.composition_year = 1725
WHERE piece.id = 15471 AND piece.composer_id = 4 AND piece.composition_year IS NULL;

UPDATE piece_parts part
JOIN pieces p ON p.id = part.piece_id

SET part.parent_part_id = NULL,
    part.linked_piece_id = NULL,
    part.sequence_number = 1, part.movement_number = NULL,
    part.name_ko = '영국 모음곡 1번 A장조', part.name_en = 'English Suite No. 1 in A major',
    part.editorial_status = 'EDITOR_REVIEWED', part.editor_locked = 1
WHERE p.id = 15471 AND p.composer_id = 4 AND part.part_key = 'musicbrainz:efe4d687-7173-4553-bf72-ff2e88d69602' AND (part.editor_locked = 0 OR (part.origin = 'manual' AND part.editorial_status = 'FACTS_VERIFIED'));

