    (composer_id, title, title_en, type, opus_number, catalogue_system, catalogue_number, composition_year, origin, editor_locked)
SELECT c.id, '이탈리아 협주곡 F장조', 'Italian Concerto in F major', 'album', 'BWV 971', NULL, NULL, 1735, 'manual', 1
FROM composers c
WHERE c.id = 4
AND NOT EXISTS (
    SELECT 1 FROM pieces existing
    WHERE existing.composer_id = c.id AND existing.title = '이탈리아 협주곡 F장조'
)
AND NOT EXISTS (
    SELECT 1 FROM piece_identifiers taken
    WHERE taken.namespace = 'musicbrainz_work' AND taken.external_id = '97a2c256-65d3-4da7-a633-6624261a7cf4'
);

INSERT INTO piece_identifiers (piece_id, namespace, external_id)
SELECT p.id, 'musicbrainz_work', '97a2c256-65d3-4da7-a633-6624261a7cf4'
FROM pieces p
WHERE p.composer_id = 4 AND p.title = '이탈리아 협주곡 F장조' AND p.origin = 'manual'
AND NOT EXISTS (
    SELECT 1 FROM piece_identifiers taken
    WHERE taken.namespace = 'musicbrainz_work' AND taken.external_id = '97a2c256-65d3-4da7-a633-6624261a7cf4'
);

